func mark(t *testing.T, name string) { t.Helper(); root := os.Getenv("SEMIO_GO_DISPATCH_MARKERS"); if root == "" { t.Fatal("marker root") }; if err := os.WriteFile(filepath.Join(root, name), []byte(name), 0o644); err != nil { t.Fatal(err) } }
func TestSelectedDefinition(t *testing.T) { if value() != 5 { t.Fatal("value") }; mark(t, "selected") }
func TestBundlePeer(t *testing.T) { mark(t, "peer") }
